# Sevlink local UI repair, invoice upload and explicit deposit verification update. Run in Windows PowerShell.
# Replaces two JavaScript, two CSS and two Python workflow files only. No database, uploads, configuration or AWS changes.
& {
  $ErrorActionPreference = 'Stop'
  $target = Join-Path $env:USERPROFILE 'OneDrive\Desktop\SEVLINK\Sevlink test 4\sevlink-platform-development-phase-1-foundations\portal\production'
  if (!(Test-Path -LiteralPath (Join-Path $target 'manage.py') -PathType Leaf)) {
    throw 'Existing Sevlink test 4 installation not found. Nothing changed. Send this error to Codex.'
  }
  $files = @(
    @{ Name = 'static/maintenance.js'; Hash = '1b5309241e8a39de0690d2d036160a77f24bbffc98b13c5b3659f066fea0c129'; Data = '' },
    @{ Name = 'static/workflow-ui.js'; Hash = '553fc4880a968878f99a385223e7c79bec0610c09e5429c47d37df32ef4ea771'; Data = '' },
    @{ Name = 'static/workflow.css'; Hash = '671cdfc699ea21da0c860174717de70aff314344d220d289d785cd6f7e904122'; Data = '' },
    @{ Name = 'static/calendar.css'; Hash = 'e1c449a97aefab3cc78ecfe45e261150588a66f0328819b1177e2f0ad2e35e1e'; Data = '' },
    @{ Name = 'portal/customer_portal.py'; Hash = '0b181f902b4a4585b26f9e5ef3b10998762103757229716521d8a3f1d554a459'; Data = '' },
    @{ Name = 'portal/workflow.py'; Hash = 'fc39de5f6f103ca034e9ec2d953ee6766490dad1b3696b8d95478ab61ed7f22a'; Data = '' }
  )
  $decoded = @{}
  foreach ($file in $files) {
    $destination = Join-Path $target $file.Name
    if (!(Test-Path -LiteralPath $destination -PathType Leaf)) { throw ('Existing file missing: ' + $destination + '. Nothing changed.') }
    $compressed = [Convert]::FromBase64String($file.Data)
    $inputStream = [IO.MemoryStream]::new($compressed)
    $gzipStream = [IO.Compression.GZipStream]::new($inputStream, [IO.Compression.CompressionMode]::Decompress)
    $outputStream = [IO.MemoryStream]::new()
    try { $gzipStream.CopyTo($outputStream); $bytes = $outputStream.ToArray() }
    finally { $gzipStream.Dispose(); $inputStream.Dispose(); $outputStream.Dispose() }
    $sha = [Security.Cryptography.SHA256]::Create()
    try { $hash = [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace('-', '').ToLowerInvariant() }
    finally { $sha.Dispose() }
    if ($hash -ne $file.Hash) { throw 'Update integrity check failed. Nothing changed.' }
    $decoded[$file.Name] = $bytes
  }
  $sourceText = [Text.Encoding]::UTF8.GetString($decoded['static/maintenance.js'])
  if ($sourceText.Contains('Save urgency') -or !$sourceText.Contains('showInvoiceUpload')) { throw 'Wrong update contents. Nothing changed.' }
  $backup = Join-Path $target ('sevlink-ui-backup-' + [Guid]::NewGuid().ToString('N'))
  New-Item -ItemType Directory -Path $backup | Out-Null
  foreach ($file in $files) { Copy-Item -LiteralPath (Join-Path $target $file.Name) -Destination (Join-Path $backup ([IO.Path]::GetFileName($file.Name))) }
  try {
    foreach ($file in $files) { [IO.File]::WriteAllBytes((Join-Path $target $file.Name), $decoded[$file.Name]) }
    foreach ($file in $files) {
      $actual = (Get-FileHash -LiteralPath (Join-Path $target $file.Name) -Algorithm SHA256).Hash.ToLowerInvariant()
      if ($actual -ne $file.Hash) { throw ('Saved file check failed: ' + $file.Name) }
    }
  } catch {
    foreach ($file in $files) { Copy-Item -LiteralPath (Join-Path $backup ([IO.Path]::GetFileName($file.Name))) -Destination (Join-Path $target $file.Name) -Force }
    throw
  }
  Write-Host ''
  Write-Host 'SUCCESS: All six website files replaced and verified.' -ForegroundColor Green
  Write-Host 'Removed: the repeated Save urgency / deposit panel.'
  Write-Host 'Added: upload progress, visible errors and saved-invoice confirmation.'
  Write-Host ('Updated project: ' + $target)
  Write-Host ('Original files backed up at: ' + $backup)
  Write-Host 'Deposit invoices now require recorded payment AND explicit Sevlink verification before scheduling.'
  Write-Host 'Restart your local Django server, close the open job, press Ctrl+F5, then reopen it.'
}
